def semantic_function(ctx):
    '''Predict the pressure exerted by a confined perfect gas from its amount, temperature and container volume using the perfect gas equation.'''
    narrate(ctx, 'Predicting the pressure of a confined perfect gas from the perfect gas equation pV = nRT')
    amount_text = load(ctx, 'the amount of substance of the gas with unit (number of moles n)', d_type=str)
    formula = load(ctx, 'the chemical formula of the gas with its physical state label', d_type=str)
    volume_text = load(ctx, 'the volume of the container holding the gas with unit', d_type=str)
    temperature_text = load(ctx, 'the temperature of the gas with unit', d_type=str)
    species = load(ctx, 'the common name of the gas species', d_type=str)
    narrate(ctx, 'Gas: ' + str(species) + ' (' + str(formula) + ')')
    narrate(ctx, 'Amount given as ' + str(amount_text))
    narrate(ctx, 'Container volume given as ' + str(volume_text))
    narrate(ctx, 'Temperature given as ' + str(temperature_text))
    n = float(str(amount_text).split()[0])
    narrate(ctx, 'Amount of substance n = ' + str(n) + ' mol')
    volume_result = do(ctx, 'Convert a container volume given with its unit to cubic metres', payloads={'the volume of the container holding the gas with unit': volume_text})
    V = float(load(volume_result, 'volume in cubic metres', d_type=float, ctx=ctx))
    narrate(ctx, 'Container volume V = ' + str(V) + ' m3')
    temperature_result = do(ctx, 'Convert a temperature given with its unit to kelvin', payloads={'the temperature of the gas with unit': temperature_text})
    T = float(load(temperature_result, 'absolute temperature in kelvin', d_type=float, ctx=ctx))
    narrate(ctx, 'Absolute temperature T = ' + str(T) + ' K')
    pressure_result = do(ctx, 'Compute the pressure of a perfect gas from its amount, absolute temperature and volume using p = nRT/V', payloads={'amount of substance in mol': n, 'absolute temperature in kelvin': T, 'volume in cubic metres': V})
    p_pa = float(load(pressure_result, 'pressure in pascals', d_type=float, ctx=ctx))
    narrate(ctx, 'Predicted pressure p = ' + str(p_pa) + ' Pa')
    check_result = do(ctx, 'Check that a predicted perfect gas pressure is insensitive to rounding the temperature to 300 K.', payloads={'amount of substance in mol': n, 'volume in cubic metres': V, 'absolute temperature in kelvin': T, 'pressure in pascals': p_pa})
    agrees = load(check_result, 'pressure agrees at the rounded temperature to the stated significant figures', d_type=bool, ctx=ctx)
    narrate(ctx, 'Rounding-sensitivity check passes: ' + str(agrees))
    units_result = do(ctx, 'Express a pressure given in pascals in megapascals, bar and atmospheres for reference.', payloads={'pressure in pascals': p_pa})
    p_mpa = float(load(units_result, 'pressure in megapascals', d_type=float, ctx=ctx))
    p_bar = float(load(units_result, 'pressure in bar', d_type=float, ctx=ctx))
    p_atm = float(load(units_result, 'pressure in atmospheres', d_type=float, ctx=ctx))
    rounded_result = do(ctx, 'Round a computed value to a stated number of significant figures and attach its unit.', payloads={'computed value': p_mpa, 'unit of the computed value': 'MPa', 'number of significant figures to report': 3})
    p_report = load(rounded_result, 'rounded value with unit', d_type=str, ctx=ctx)
    narrate(ctx, 'Reported pressure: ' + str(p_report) + ' (' + str(p_bar) + ' bar, ' + str(p_atm) + ' atm)')
    return {'predicted pressure of the gas with unit': p_report, 'pressure in pascals': p_pa, 'pressure in bar': p_bar, 'pressure in atmospheres': p_atm, 'rounding sensitivity check agrees': agrees}